/**
 * Slider. A molded cap knob with an accent grip line, in a recessed track
 * whose filled portion is lit in the accent. Composes var(--echo-*).
 *
 * The fill is light INSIDE the well, never a halo around it: no control in the
 * library throws an outer glow, and the slider was the last one that did.
 */
.echo-slider {
  position: relative;
  /* Fluid, capped at the old fixed width. */
  width: 100%;
  max-width: 260px;
}

.echo-slider__control {
  display: flex;
  align-items: center;
  /* Never narrower than its own knob: squeezed to nothing, the knob was the
     one thing left sticking out of the row. */
  min-width: 1.75rem;
  height: var(--echo-control-compact);
  cursor: pointer;
  touch-action: none;
}

.echo-slider__track {
  position: relative;
  width: 100%;
  height: 10px;
  border-radius: var(--echo-radius-full);
  /* Deep recessed well — same near-black recipe as the Field. */
  background: var(--echo-drawn-hollow, linear-gradient(
    160deg,
    color-mix(in oklab, var(--echo-well) 72%, var(--echo-shade-ink, black)),
    color-mix(in oklab, var(--echo-lcd) 88%, var(--echo-shade-ink, black))
  ));
  box-shadow: var(
    --echo-shadow-well,
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent)
  );
}

/* The rail clips the fill: the fill slides with the knob (see slider.tsx),
   and its extension off the start edge must not show outside the well. */
.echo-slider__rail {
  position: absolute;
  inset: 0;
  /* Explicit, not just implied by inset: Base UI sizes the fill with
     height: inherit, which reads this property, not the used height. */
  height: 100%;
  overflow: hidden;
  border-radius: inherit;
}

.echo-slider__indicator {
  position: absolute;
  height: 100%;
  border-radius: var(--echo-radius-full);
  /* Drawn, the travel is the accent as a flat fill under the ink. */
  background: var(--echo-drawn-fill, linear-gradient(90deg, var(--echo-accent-5) 0%, var(--echo-accent-glow) 100%));
  /* A lit top edge, inside the fill — the light sits in the rail. None on a drawn device. */
  box-shadow: inset 0 calc(1px * (1 - var(--echo-drawn, 0))) 0 color-mix(in oklch, var(--echo-accent-highlight) 45%, transparent);
}
/* While the fill trails the knob it slides away from the rail's start; this
   keeps the start covered. The rail clips it. */
.echo-slider__indicator::before {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline-end: calc(100% - 5px);
  width: 400px;
  background: var(--echo-drawn-fill, var(--echo-accent-5));
  box-shadow: inherit;
}

/*
 * The thumb is Base UI's positioning shell and the focus target's parent; it
 * draws nothing. What you see is the cap inside it, which physics moves:
 * --lift raises it toward the key light, casting a longer, softer shadow.
 */
.echo-slider__thumb {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
}

.echo-slider__travel {
  display: flex;
  width: 100%;
  height: 100%;
  will-change: transform;
}

/* Molded fader knob (reference material.buttonCap, 4 stops) with a grip line. */
.echo-slider__cap {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border-radius: var(--echo-radius-full);
  /* Drawn, the knob is the value, filled in solid ink. */
  background: var(--echo-drawn-ink, linear-gradient(
    180deg,
    var(--echo-cap-highlight) 0%,
    color-mix(in oklab, var(--echo-cap-highlight) 50%, var(--echo-cap)) 40%,
    var(--echo-cap) 62%,
    var(--echo-cap-shadow) 100%
  ));
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.42 * var(--echo-gloss, 1))),
    /* Drawn: a paper ring knocks the knob out of a fill as dark as it is. */
    0 0 0 calc(2px * var(--echo-drawn, 0)) var(--echo-surface),
    0 calc(3px + 6px * var(--lift, 0)) calc(6px + 12px * var(--lift, 0))
      color-mix(in oklab, var(--echo-cast-ink, black) calc(0.55 * var(--echo-shade, 1) * 100%), transparent);
  will-change: transform;
}
/* Focus lands on the visually hidden range input inside the thumb, so the
   thumb matches :has(), never :focus-visible itself (BUG-3). */
.echo-slider__thumb:has(:focus-visible) {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  border-radius: var(--echo-radius-full);
}
.echo-slider__thumb:has(:focus-visible) .echo-slider__cap {
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.42 * var(--echo-gloss, 1))),
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow));
}
.echo-slider__grip {
  width: 2px;
  height: 12px;
  border-radius: var(--echo-radius-full);
  background: var(--echo-accent-glow);
  /* Lifted, the grip line lights up. */
  box-shadow: 0 0 calc(6px * var(--lift, 0) * (1 - var(--echo-drawn, 0))) var(--echo-accent-glow);
}

.echo-slider[data-disabled] {
  opacity: 0.45;
}

/*
 * Coarse-pointer target.
 *
 * The knob is 28px. What actually receives the tap is Base UI's native range
 * input inside it, so the input is what has to grow — a transparent pad on the
 * thumb would look right and catch nothing. The input is invisible and
 * position: fixed over the knob, so growing it costs no visual change: the
 * moulded knob stays 28px and the finger gets 44.
 */
@media (pointer: coarse) {
  .echo-slider__thumb > input {
    width: 44px;
    height: 44px;
    transform: translate(-8px, -8px);
  }
}

/* Small: a 6px rail and a 20px knob, for dense rows. */
.echo-slider[data-size="sm"] .echo-slider__control {
  height: var(--echo-control-compact);
}

.echo-slider[data-size="sm"] .echo-slider__track {
  height: 6px;
}

.echo-slider[data-size="sm"] .echo-slider__thumb {
  width: 20px;
  height: 20px;
}

.echo-slider[data-size="sm"] .echo-slider__grip {
  height: 8px;
}

/*
 * Forced colors (Windows High Contrast) drops gradients and shadows, which is
 * everything that draws this control's state. System colors draw it instead;
 * nothing here sets forced-color-adjust: none, so focus outlines still show.
 */
@media (forced-colors: active) {
  .echo-slider__track {
    background: Canvas;
    border: var(--echo-border-hairline, 1px) solid ButtonText;
  }
  .echo-slider__indicator {
    background: Highlight;
  }
  .echo-slider__cap {
    background: ButtonText;
    border: var(--echo-border-thick, 2px) solid Canvas;
  }
  .echo-slider__grip {
    background: Canvas;
  }
}

"use client";

/**
 * Slider. Base UI Slider behavior (keyboard,
 * drag, track-press, a11y) with a recessed rail + molded knob and a scrubbing
 * tick sound on each step — very hardware.
 *
 * The knob has mass, and it keeps its shape. Base UI puts the thumb at the
 * value instantly — the value, the range input and the screen reader never
 * wait — and the knob's visible parts catch up on a real spring:
 *   - hovered, it rises and leans toward the pointer;
 *   - held, it grows and lifts off the rail, the way a touched control does
 *     on iOS, and stays glued to the hand while dragged;
 *   - pulled past either end, it rubber-bands, giving less the further you go;
 *   - a press on the rail throws it across, landing with a little bounce.
 * The lit fill rides with the knob, so the light always ends under it.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import { forwardRef, useCallback, useEffect, useRef } from "react";
import gsap from "gsap";
import { Slider as BaseSlider } from "@base-ui/react/slider";
import type { EchoInterop, EchoSliderChangeEvent } from "echo-ui-core/types";
import { useSoundOptional } from "echo-ui-core/sound";
import { springs } from "echo-ui-core/motion";
import {
  createSpring,
  rubberband,
  timing,
  useReducedMotionRef,
  watchTravel,
  type Spring,
} from "echo-ui-core/tactile";
import "./slider.css";

export type SliderSize = "sm" | "md";

interface SliderOwnProps extends EchoInterop {
  /**
   * `md` (default) is the fader: a 10px rail and a 28px knob. `sm` is a
   * 6px rail and a 20px knob, for dense rows — inline settings, a mixer strip,
   * a control inside a table. Two sizes, not a scale: a slider is either the
   * control you came for or one of many.
   */
  size?: SliderSize;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number, eventDetails: EchoSliderChangeEvent) => void;
  min?: number;
  max?: number;
  step?: number;
}

/**
 * A control has to have a name: `aria-label`, or
 * `aria-labelledby` pointing at visible text. Leaving both out is a type
 * error, so it gets decided rather than forgotten.
 */
type AccessibleName =
  | { "aria-label": string; "aria-labelledby"?: string }
  | { "aria-labelledby": string; "aria-label"?: string };

export type SliderProps = SliderOwnProps & AccessibleName;

/** `forwardRef`, not a `ref` prop — see the note on `Field`. */
export const Slider = forwardRef<HTMLDivElement, SliderProps>(function Slider(
  {
    size = "md",
    onValueChange,
    defaultValue = 50,
    "aria-label": ariaLabel,
    "aria-labelledby": ariaLabelledby,
    ...props
  },
  ref,
) {
  const sound = useSoundOptional();
  const last = useRef<number | null>(null);
  const reduced = useReducedMotionRef();
  const track = useRef<HTMLDivElement | null>(null);
  const thumb = useRef<HTMLDivElement | null>(null);
  const travel = useRef<HTMLSpanElement | null>(null);
  const cap = useRef<HTMLSpanElement | null>(null);
  const fill = useRef<HTMLDivElement | null>(null);
  const hovered = useRef(false);
  const dragging = useRef(false);
  // Two springs, summed: how far the knob still has to travel to its value,
  // and how far it is being pulled past an end.
  const lag = useRef<Spring | null>(null);
  const pull = useRef<Spring | null>(null);

  useEffect(() => {
    const t = thumb.current;
    const r = track.current;
    if (!t || !r) return;
    const draw = () => {
      const x = (lag.current?.value ?? 0) + (pull.current?.value ?? 0);
      gsap.set([travel.current, fill.current], { x });
    };
    lag.current = createSpring(0, springs.bouncy, draw);
    pull.current = createSpring(0, springs.bouncy, draw);

    /*
     * Base UI moves the thumb by rewriting its inline --position; watchTravel
     * sees each move before paint. The spring absorbs the jump and carries
     * the knob the rest of the way — keeping whatever momentum it had, so a
     * knob redirected mid-flight bends rather than stopping dead.
     */
    const stop = watchTravel({
      part: t,
      frame: r,
      on: t,
      attributes: ["style"],
      onMove: (dx) => {
        const spring = lag.current;
        if (!spring || reduced.current) return;
        const jump = Math.abs(dx) > 20;
        spring.shift(dx);
        spring.to(0, {
          config: jump ? springs.bouncy : dragging.current ? springs.track : springs.snappy,
        });
      },
    });

    // Pulled past an end while held: rubber-band the knob after the pointer.
    const moved = (e: PointerEvent) => {
      if (!dragging.current || reduced.current || !pull.current) return;
      const rr = r.getBoundingClientRect();
      const over = e.clientX < rr.left ? e.clientX - rr.left : e.clientX > rr.right ? e.clientX - rr.right : 0;
      pull.current.to(rubberband(over, 36), { config: springs.track });
    };
    window.addEventListener("pointermove", moved);

    const parts = [travel.current, cap.current, fill.current];
    return () => {
      stop();
      window.removeEventListener("pointermove", moved);
      lag.current?.stop();
      pull.current?.stop();
      gsap.killTweensOf(parts);
    };
  }, [reduced]);

  /*
   * The knob's pose. It never deforms: hovered it rises a little, held it
   * grows and lifts clear of the rail, and it keeps its round shape throughout.
   */
  const pose = useCallback(
    (name: "lift" | "rebound") => {
      const c = cap.current;
      if (!c) return;
      const held = dragging.current;
      const up = hovered.current || held;
      const vars = { "--lift": held ? 1 : up ? 0.6 : 0 };
      if (reduced.current) {
        gsap.set(c, vars);
        return;
      }
      gsap.to(c, {
        ...timing(name),
        overwrite: "auto",
        ...vars,
        scale: held ? 1.22 : up ? 1.1 : 1,
        ...(held || !up ? { x: 0 } : {}),
      });
    },
    [reduced],
  );

  useEffect(() => {
    const up = () => {
      if (!dragging.current) return;
      dragging.current = false;
      pull.current?.to(0, { config: springs.bouncy });
      pose("rebound");
    };
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
    return () => {
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
    };
  }, [pose]);

  return (
    <BaseSlider.Root
      ref={ref}
      className="echo-slider"
      data-size={size}
      defaultValue={defaultValue}
      onValueChange={(value, eventDetails) => {
        // Tick once per step change (Base UI already fires on change).
        if (value !== last.current) {
          last.current = value;
          sound?.play("tap");
        }
        onValueChange?.(value, eventDetails);
      }}
      {...props}
    >
      <BaseSlider.Control
        className="echo-slider__control"
        onPointerEnter={(e) => {
          if (e.pointerType !== "mouse" || props.disabled) return;
          hovered.current = true;
          pose("lift");
        }}
        onPointerMove={(e) => {
          // Leaning toward the pointer: the knob notices you before you touch it.
          const c = cap.current;
          const t = thumb.current;
          if (!c || !t || e.pointerType !== "mouse" || dragging.current || reduced.current) return;
          if (props.disabled) return;
          const tr = t.getBoundingClientRect();
          const d = e.clientX - (tr.left + tr.width / 2);
          gsap.to(c, { ...timing("follow"), overwrite: "auto", x: Math.max(-6, Math.min(6, d * 0.12)) });
        }}
        onPointerLeave={() => {
          hovered.current = false;
          if (!dragging.current) pose("rebound");
        }}
        onPointerDown={(e) => {
          if (e.button !== 0 || props.disabled) return;
          dragging.current = true;
          pose("lift");
        }}
      >
        <BaseSlider.Track ref={track} className="echo-slider__track">
          {/* The rail clips the fill, which slides with the knob. */}
          <span className="echo-slider__rail" aria-hidden>
            <BaseSlider.Indicator ref={fill} className="echo-slider__indicator" />
          </span>
          {/* aria-label goes on the Thumb, which owns the hidden range input. */}
          <BaseSlider.Thumb
            ref={thumb}
            className="echo-slider__thumb"
            aria-label={ariaLabel}
            aria-labelledby={ariaLabelledby}
          >
            <span ref={travel} className="echo-slider__travel" aria-hidden>
              <span ref={cap} className="echo-slider__cap">
                <span className="echo-slider__grip" />
              </span>
            </span>
          </BaseSlider.Thumb>
        </BaseSlider.Track>
      </BaseSlider.Control>
    </BaseSlider.Root>
  );
});
